26	/** Class to work with the shell toolchain, e.g. get the shell interpreter's path. */
27	public final class ShToolchain {
28	
29	  private static PathFragment getHostOrDefaultPath() {
30	    OS current = OS.getCurrent();
31	    if (!ShellConfiguration.getShellExecutables().containsKey(current)) {
32	      current = OS.UNKNOWN;
33	    }
34	    Preconditions.checkState(
35	        ShellConfiguration.getShellExecutables().containsKey(current),
36	        "shellExecutableFinder should set a value with key '%s'",
37	        current);
38	
39	    return ShellConfiguration.getShellExecutables().get(current);
40	  }
41	
42	  /** Returns the default shell executable's path for the host OS. */
43	  public static PathFragment getPathForHost(BuildConfigurationValue config) {
44	    return getPathForPlatform(config, null);
45	  }
46	
47	  /**
48	   * Returns the shell executable's path. Prefers, in order
49	   *
50	   * <p>1) the default path set by {@code --shell_executable}
51	   *
52	   * <p>2) the path for the provided platform
53	   *
54	   * <p>3) the path for the host platform
55	   *
56	   * <p>4) a hard-coded default path.
57	   */
58	  public static PathFragment getPathForPlatform(
59	      BuildConfigurationValue config, @Nullable PlatformInfo platformInfo) {
60	    ShellConfiguration shellConfiguration = config.getFragment(ShellConfiguration.class);
61	
62	    if (shellConfiguration != null && shellConfiguration.getOptionsBasedDefault() != null) {
63	      return shellConfiguration.getOptionsBasedDefault();
64	    }
65	
66	    if (platformInfo != null) {
67	      for (OS os : ShellConfiguration.getShellExecutables().keySet()) {
68	        if (platformInfo.constraints().hasConstraintValue(OS_TO_CONSTRAINTS.get(os))) {
69	          return ShellConfiguration.getShellExecutables().get(os);
70	        }
71	      }
72	    }
73	    return getHostOrDefaultPath();
74	  }
75	
76	  private ShToolchain() {}
77	}
